insert into public.digital_plans (slug, name, tagline, description, best_for, monthly_price_paise, setup_fee_paise, price_is_starting, commitment_months, is_recommended, featured_on_homepage, sort_order, limits, exclusions, maintenance, terms, faqs) values ('launch', 'Launch', 'A professional website to get your business online.', 'A clean, fast business website of up to five pages, connected to WhatsApp and Google Maps, with basic SEO and the essential upkeep handled every month.', 'New and small businesses that need a credible online presence quickly.', 99900, 299900, false, 12, false, true, 1, '[{"label":"Pages","value":"Up to 5"},{"label":"Design","value":"Professionally designed layout, adapted to your brand"},{"label":"Design revisions during setup","value":"2 rounds"},{"label":"Monthly content updates","value":"Up to 2 minor text or image changes"}]'::jsonb, '["Admin panel or content management system","Meta Pixel and Google Analytics setup (available as add-ons)","Online payments or e-commerce","Social media creatives","Domain and hosting charges, where separate"]'::jsonb, 'Security and SSL checks, a monthly backup, uptime monitoring and up to two minor content changes a month. New pages or new features are quoted separately.', 'The one-time setup fee is paid before work starts and is not refundable once work has begun. The monthly fee is billed in advance from the month the website goes live. Website-development plans carry a minimum commitment of 12 months; after it, the plan continues month to month until either side gives 30 days'' written notice. Leaving within the minimum commitment means paying the remaining months of that commitment. GST is charged extra as applicable. The signed quotation is the final word on scope, price and term.', '[{"question":"Can I move up to a bigger plan later?","answer":"Yes. You pay the difference in setup work, if any, and the new monthly fee from the next billing month."},{"question":"Do I need to provide the content?","answer":"You provide your business details, photos and the text you want to say. We shape it into pages and can suggest wording."}]'::jsonb) on conflict (slug) do nothing;
