insert into public.digital_plans (slug, name, tagline, description, best_for, monthly_price_paise, setup_fee_paise, price_is_starting, commitment_months, is_recommended, featured_on_homepage, sort_order, limits, exclusions, maintenance, terms, faqs) values ('business-plus', 'Business Plus', 'A custom-designed website you can manage yourself.', 'Up to ten custom-designed pages with a basic admin panel for enquiries, plus Meta Pixel, Google Analytics, on-page SEO and social profile integration.', 'Established businesses that want a distinctive website and to start measuring results.', 199900, 499900, false, 12, false, false, 2, '[{"label":"Pages","value":"Up to 10"},{"label":"Design revisions during setup","value":"3 rounds"},{"label":"Admin panel","value":"Manage enquiries and basic page content"},{"label":"Monthly content updates","value":"Up to 4 minor text or image changes"}]'::jsonb, '["Blog or dynamic CMS","Social media creatives","Paid advertising management and ad budget","Online payments or e-commerce","Domain and hosting charges, where separate"]'::jsonb, 'Monthly security updates, backups, uptime monitoring, analytics checks and up to four minor content changes a month.', 'The one-time setup fee is paid before work starts and is not refundable once work has begun. The monthly fee is billed in advance from the month the website goes live. Website-development plans carry a minimum commitment of 12 months; after it, the plan continues month to month until either side gives 30 days'' written notice. Leaving within the minimum commitment means paying the remaining months of that commitment. GST is charged extra as applicable. The signed quotation is the final word on scope, price and term.', '[{"question":"What can I change from the admin panel?","answer":"You can view and manage enquiries and update the basic content blocks we set up for you. Layout changes are done by our team."},{"question":"Is Meta Pixel the same as running ads?","answer":"No. The Pixel measures visits and enquiries for your Facebook and Instagram ads. Running ads is a separate add-on, and the ad budget is paid by you."}]'::jsonb) on conflict (slug) do nothing;
