insert into public.digital_plans (slug, name, tagline, description, best_for, monthly_price_paise, setup_fee_paise, price_is_starting, commitment_months, is_recommended, featured_on_homepage, sort_order, limits, exclusions, maintenance, terms, faqs) values ('growth-pro', 'Growth Pro', 'A website that brings in leads, and the tools to follow them up.', 'Up to twenty pages with an advanced admin dashboard, a dynamic CMS and blog, lead management, advanced SEO, conversion tracking and up to eight social media creatives every month.', 'Growing businesses that rely on the website for enquiries and want SEO and social media looked after.', 399900, 999900, false, 12, true, true, 3, '[{"label":"Pages","value":"Up to 20"},{"label":"Social media creatives","value":"Up to 8 per month, not carried over"},{"label":"Design revisions during setup","value":"3 rounds"},{"label":"Blog","value":"CMS and blog set up; writing articles is the Blog management add-on"}]'::jsonb, '["Writing blog articles (Blog management add-on)","Posting and community management (Social media management add-on)","Paid advertising management and ad budget","Online payments or e-commerce","Domain, hosting and third-party tool subscriptions, where separate"]'::jsonb, 'Technical maintenance, regular backups, security and performance monitoring, SEO health checks and fixes, and help with content updates through the dashboard.', 'The one-time setup fee is paid before work starts and is not refundable once work has begun. The monthly fee is billed in advance from the month the website goes live. Website-development plans carry a minimum commitment of 12 months; after it, the plan continues month to month until either side gives 30 days'' written notice. Leaving within the minimum commitment means paying the remaining months of that commitment. GST is charged extra as applicable. The signed quotation is the final word on scope, price and term.', '[{"question":"Why is Growth Pro recommended?","answer":"For most businesses that want enquiries from their website, it is the smallest plan that includes lead management, advanced SEO and regular social media creatives together. If you only need a presence online, Launch or Business Plus may suit you better."},{"question":"Do the 8 creatives include posting them?","answer":"The creatives are designed and delivered to you. Scheduling, posting and replying are part of the Social media management add-on."}]'::jsonb) on conflict (slug) do nothing;
