insert into public.digital_plans (slug, name, tagline, description, best_for, monthly_price_paise, setup_fee_paise, price_is_starting, commitment_months, is_recommended, featured_on_homepage, sort_order, limits, exclusions, maintenance, terms, faqs) values ('commerce-pro', 'Commerce Pro', 'A complete online store, set up and looked after.', 'An e-commerce website with up to 100 initial products, inventory, cart and checkout, Razorpay and COD, orders, coupons, shipping integration, sales analytics and product SEO.', 'Businesses that want to sell products online with their own store.', 799900, 1499900, false, 12, false, false, 4, '[{"label":"Products at launch","value":"Up to 100 uploaded by us; more at ₹30 per product"},{"label":"Payment gateway","value":"Razorpay account in your business name; gateway fees are charged by Razorpay"},{"label":"Shipping","value":"Integration with one supported shipping partner; courier charges are separate"},{"label":"Design revisions during setup","value":"3 rounds"}]'::jsonb, '["Payment gateway transaction fees","Shipping and courier charges","Product photography and writing product descriptions","Paid advertising management and ad budget","Domain, hosting and third-party app subscriptions, where separate"]'::jsonb, 'Technical maintenance of the store, security and performance monitoring, backups, and fixing faults in checkout, payments or order flow. Bulk product uploads after launch are charged per product.', 'The one-time setup fee is paid before work starts and is not refundable once work has begun. The monthly fee is billed in advance from the month the website goes live. Website-development plans carry a minimum commitment of 12 months; after it, the plan continues month to month until either side gives 30 days'' written notice. Leaving within the minimum commitment means paying the remaining months of that commitment. GST is charged extra as applicable. The signed quotation is the final word on scope, price and term.', '[{"question":"Who owns the Razorpay account?","answer":"You do. The account is opened in your business name and payments settle to your bank. We integrate it with the store."},{"question":"Can I add more than 100 products?","answer":"Yes. You can add products yourself from the admin panel at no charge, or have us upload them at ₹30 per product."}]'::jsonb) on conflict (slug) do nothing;
