insert into public.digital_plans (slug, name, tagline, description, best_for, monthly_price_paise, setup_fee_paise, price_is_starting, commitment_months, is_recommended, featured_on_homepage, sort_order, limits, exclusions, maintenance, terms, faqs) values ('enterprise-360', 'Enterprise 360', 'Custom software, automation and growth, run as one programme.', 'A fully customised website or web application with a custom admin dashboard, CRM and workflows, API integrations, automation, managed SEO and digital growth, dedicated support and monthly reporting.', 'Businesses with their own processes to digitise, or several services to run together.', 1499900, 2999900, true, 12, false, true, 5, '[{"label":"Scope","value":"Set out in a written scope and quotation before work starts"},{"label":"Development hours","value":"A monthly allocation agreed in the quotation; extra hours quoted separately"},{"label":"Social media creatives","value":"Up to 12 per month, as agreed"},{"label":"Price","value":"From ₹14,999 a month and ₹29,999 setup; the quotation sets the final figure"}]'::jsonb, '["Work outside the agreed scope (quoted separately)","Paid advertising budget","Third-party software, API and SMS/WhatsApp provider charges","Domain, hosting and cloud infrastructure charges, where separate"]'::jsonb, 'Technical maintenance of the application and integrations, monitoring, backups, security updates and a monthly performance report, with a named support allocation for your account.', 'The one-time setup fee is paid before work starts and is not refundable once work has begun. The monthly fee is billed in advance from the month the website goes live. Website-development plans carry a minimum commitment of 12 months; after it, the plan continues month to month until either side gives 30 days'' written notice. Leaving within the minimum commitment means paying the remaining months of that commitment. GST is charged extra as applicable. The signed quotation is the final word on scope, price and term.', '[{"question":"Why is the price shown as \"onwards\"?","answer":"Enterprise work is scoped to your processes. The figures shown are where it starts; your quotation sets the final monthly and setup price before anything is agreed."},{"question":"Can you integrate our existing software?","answer":"Usually, if it offers an API or export. We confirm what is possible during discovery, before the quotation."}]'::jsonb) on conflict (slug) do nothing;
